def transcript_has_assistant_after(raw_events: list[dict], after_index: int) -> bool:
    for ev in raw_events[after_index + 1 :]:
        if ev.get("type") == "assistant":
            return True
        msg = ev.get("message") or {}
        if (msg.get("role") or "").lower() == "assistant":
            return True
    return False


def find_last_user_index(raw_events: list[dict]) -> int | None:
    """Return index of the latest top-level user event, or None."""
    for i in range(len(raw_events) - 1, -1, -1):
        if raw_events[i].get("type") == "user":
            return i
    return None


def wait_for_assistant_flush(
    transcript_path: Path,
    raw_events: list[dict],
    *,
    hook_event: str,
    max_wait_s: float | None = None,
) -> list[dict]:
    """Mitigate Claude Code hook race: assistant rows may land after Stop/SessionEnd starts.

    Stop defaults to 4s poll; SessionEnd / UserPromptSubmit default to 8s.
    Override via SESSION_LOG_STOP_WAIT_S / SESSION_LOG_SESSIONEND_WAIT_S.
    """
    if max_wait_s is None:
        if hook_event in ("SessionEnd", "UserPromptSubmit"):
            max_wait_s = float(os.environ.get("SESSION_LOG_SESSIONEND_WAIT_S", "8"))
        else:
            max_wait_s = float(os.environ.get("SESSION_LOG_STOP_WAIT_S", "4"))

    user_idx = find_last_user_index(raw_events)
    if user_idx is None:
        return raw_events
    if transcript_has_assistant_after(raw_events, user_idx):
        return raw_events

    deadline = time.monotonic() + max(0.0, max_wait_s)
    latest = raw_events
    attempt = 0
    while time.monotonic() < deadline:
        attempt += 1
        sleep_s = min(1.0, 0.15 * attempt)
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        time.sleep(min(sleep_s, remaining))
        reloaded = load_transcript(transcript_path)
        if reloaded is None:
            continue
        latest = reloaded
        uidx = find_last_user_index(latest)
        if uidx is not None and transcript_has_assistant_after(latest, uidx):
            sys.stderr.write(
                f"[session-log] transcript flush wait succeeded after {attempt} poll(s) "
                f"(event={hook_event}, lines={len(latest)})\n"
            )
            return latest

    if len(latest) != len(raw_events):
        sys.stderr.write(
            f"[session-log] transcript grew during wait "
            f"({len(raw_events)} -> {len(latest)} lines) but no assistant yet "
            f"(event={hook_event})\n"
        )
    else:
        sys.stderr.write(
            f"[session-log] transcript still missing assistant after wait "
            f"(event={hook_event}, lines={len(latest)}, waited={max_wait_s}s)\n"
        )
    return latest



