#!/usr/bin/env python3
"""Rebuild incomplete Claude Code contest logs into the correct date folders."""
from __future__ import annotations

import json
import os
import subprocess
import sys
from collections import Counter
from pathlib import Path

dest = Path("/home/debian19y/openvela/contest2026_004_TeamFalcons")
core = Path.home() / ".claude/contest-shared/snapshot_core.py"
projects = Path.home() / ".claude/projects"
repo_member = dest / "logs/Foleaf"
staging_member = Path.home() / ".claude/contest-collector-staging/Foleaf"
man_path = repo_member / "manifest.json"
man = json.loads(man_path.read_text())


def raw_path(sid: str) -> Path | None:
    hits = list(projects.glob(f"*/{sid}.jsonl"))
    return hits[0] if hits else None


def first_day(rp: Path) -> str:
    for line in rp.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        try:
            o = json.loads(line)
        except json.JSONDecodeError:
            continue
        ts = o.get("timestamp")
        if isinstance(ts, str) and len(ts) >= 10 and ts[4] == "-" and ts[7] == "-":
            return ts[:10]
    return "2026-07-21"


def export_count(rel: str | None) -> int:
    if not rel:
        return 0
    p = dest / rel
    if not p.exists():
        # also search by sid anywhere
        return 0
    return sum(1 for line in p.read_text().splitlines() if line.strip())


def remove_session(member_dir: Path, sid: str) -> None:
    manp = member_dir / "manifest.json"
    if manp.exists():
        m = json.loads(manp.read_text())
        keep = []
        for s in m.get("sessions") or []:
            if s.get("session_id") == sid:
                continue
            keep.append(s)
        m["sessions"] = keep
        manp.write_text(json.dumps(m, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    for hit in member_dir.glob(f"*/*{sid}*.jsonl"):
        hit.unlink(missing_ok=True)
        print("  deleted", hit)


# Build target list from incomplete + any claude-code files currently under today that are historical
targets: dict[str, Path] = {}
for s in man["sessions"]:
    if s.get("tool") != "claude-code":
        continue
    sid = s["session_id"]
    rp = raw_path(sid)
    if not rp:
        continue
    raw_n = sum(1 for line in rp.read_text().splitlines() if line.strip())
    exp_n = export_count(s.get("file_path"))
    # also count any copies under wrong day
    scattered = list(repo_member.glob(f"*/claude-code__{sid}.jsonl"))
    if scattered:
        exp_n = max(exp_n, max(sum(1 for l in p.read_text().splitlines() if l.strip()) for p in scattered))
    if exp_n <= 5 and raw_n >= 15:
        targets[sid] = rp
    elif raw_n > max(exp_n, 1) * 2 and exp_n < 80 and raw_n >= 20:
        targets[sid] = rp

# Always include today sessions
for f in (repo_member / "2026-07-21").glob("claude-code__*.jsonl") if (repo_member / "2026-07-21").exists() else []:
    sid = f.name.split("__", 1)[1].removesuffix(".jsonl")
    rp = raw_path(sid)
    if rp:
        targets[sid] = rp

# Also any historical sids wrongly sitting only under 2026-07-21
if (repo_member / "2026-07-21").exists():
    for f in (repo_member / "2026-07-21").glob("claude-code__*.jsonl"):
        sid = f.name.split("__", 1)[1].removesuffix(".jsonl")
        rp = raw_path(sid)
        if not rp:
            continue
        day = first_day(rp)
        if day != "2026-07-21":
            targets[sid] = rp

print(f"will reprocess {len(targets)} sessions")

env = {**os.environ}
for line in Path.home().joinpath(".claude/contest-collector.env").read_text().splitlines():
    if "=" in line and not line.strip().startswith("#"):
        k, v = line.split("=", 1)
        env[k.strip()] = v.strip()
env["SESSION_LOG_SESSIONEND_WAIT_S"] = "0"
env["SESSION_LOG_STOP_WAIT_S"] = "0"

results = []
for sid, rp in sorted(targets.items()):
    day = first_day(rp)
    raw_n = sum(1 for _ in open(rp, encoding="utf-8"))
    print(f"\n=== {sid} -> {day} (raw={raw_n}) ===")
    remove_session(staging_member, sid)
    remove_session(repo_member, sid)
    payload = json.dumps(
        {
            "session_id": sid,
            "cwd": str(dest),
            "transcript_path": str(rp),
            "hook_event_name": "SessionEnd",
        }
    )
    r = subprocess.run(
        ["python3", str(core), "--tool", "claude-code"],
        input=payload,
        text=True,
        capture_output=True,
        env=env,
        cwd=str(dest),
    )
    print("rc", r.returncode)
    print("stderr", (r.stderr or "").strip()[:350])
    hits = list(repo_member.glob(f"*/claude-code__{sid}.jsonl"))
    n = 0
    roles = {}
    path = None
    if hits:
        path = str(hits[0].relative_to(dest))
        lines = [json.loads(l) for l in hits[0].read_text().splitlines() if l.strip()]
        n = len(lines)
        roles = dict(Counter(e.get("role") for e in lines))
    results.append((sid, day, n, roles, path, r.returncode))
    print("export", n, roles, path)

print("\n=== SUMMARY ===")
ok = 0
for sid, day, n, roles, path, rc in results:
    flag = "OK" if path and f"/{day}/" in path.replace("\\", "/") else "DATE?"
    if n > 0 and rc == 0:
        ok += 1
    print(f"{sid[:12]} day={day} n={n} {flag} path={path} roles={roles}")
print(f"done: {ok}/{len(results)} non-empty exports")

